package com.sakhtyar.config;
import org.slf4j.*;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;
@Component public class ConfigStartupReporter implements ApplicationRunner {private static final Logger log=LoggerFactory.getLogger(ConfigStartupReporter.class);private final JdbcTemplate db;public ConfigStartupReporter(JdbcTemplate db){this.db=db;}public void run(ApplicationArguments a){log.info("================ SAKHTYAR PLATFORM CONFIG ================");try{Integer n=db.queryForObject("select count(*) from platform_config_version",Integer.class);log.info("[OK] Configuration database ready; versions={}",n);}catch(Exception e){log.warn("[WARN] Configuration tables unavailable: {}",e.getMessage());}log.info("===========================================================");}}